tokenize: function(expr) {
  const tokens = [];
  let i = 0;
  const n = expr.length;

  while (i < n) {
    const char = expr[i];

    if (/\d/.test(char) || (char === '.' && i + 1 < n && /\d/.test(expr[i + 1]))) {
      let num = '';
      while (i < n && (/\d/.test(expr[i]) || expr[i] === '.')) {
        num += expr[i];
        i++;
      }
      tokens.push({ type: 'number', value: parseFloat(num) });
    } else if ('+-*/()'.includes(char)) {
      tokens.push({ type: 'operator', value: char });
      i++;
    } else if (char === ' ') {
      i++;
    } else {
      throw new Error(`Unexpected character: ${char}`);
    }
  }

  return tokens;
}

